import{_ as a,o,c as i,a2 as t}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"Proposta di aggiornamento di Specifications.md alla v1.7","description":"","frontmatter":{},"headers":[],"relativePath":"spec-v1.7-proposta.md","filePath":"spec-v1.7-proposta.md"}'),s={name:"spec-v1.7-proposta.md"};function n(l,e,c,r,d,p){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="proposta-di-aggiornamento-di-specifications-md-alla-v1-7" tabindex="-1">Proposta di aggiornamento di <code>Specifications.md</code> alla v1.7 <a class="header-anchor" href="#proposta-di-aggiornamento-di-specifications-md-alla-v1-7" aria-label="Permalink to &quot;Proposta di aggiornamento di `Specifications.md` alla v1.7&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td><strong>recepita</strong> in <code>Specifications.md</code> v1.7 il 2026-11-16 (con la nomenclatura di ADR-0052 in tutto lo spec); resta come storia del recepimento</td></tr><tr><td><strong>Data</strong></td><td>2026-11-16</td></tr><tr><td><strong>Base</strong></td><td><code>Specifications.md</code> v1.6 (15 novembre 2026), 2027 righe; i numeri di riga sono quelli di questa versione</td></tr><tr><td><strong>Fonti</strong></td><td><a href="./adr/0052-rebrand-clarae-notanda.html">ADR-0052</a>, <a href="./adr/0057-identita-dispositivo-desktop-hostname.html">0057</a>, <a href="./adr/0058-logout-completo-da-keycloak.html">0058</a>, <a href="./adr/0059-pulizia-cartella-configurazione-legacy-e-zip-coerente.html">0059</a>, <a href="./adr/0060-web-viewer-acceso-di-default.html">0060</a> e <a href="./adr/0061-budget-iniziale-console-720.html">0061</a>, tutti <strong>accettati dall&#39;owner il 2026-11-16</strong> e già implementati (1.5.0 e 1.7.2)</td></tr><tr><td><strong>Come usarla</strong></td><td>ogni voce indica la sezione e la riga, il <strong>testo attuale</strong> (citato alla lettera, in un blocco <code>text</code>) e il <strong>testo proposto</strong>. Dove il testo proposto sostituisce un frammento, si sostituisce solo quel frammento; dove si aggiunge, la voce dice dopo quale riga</td></tr></tbody></table><p>Gli ADR 0057–0061 sono il lavoro di M21 (correttivi dello schizzo del 2026-11-15, <a href="./roadmap.html">roadmap</a> §13-quaterdecies), rilasciato come 1.7.2. <a href="./adr/0052-rebrand-clarae-notanda.html">ADR-0052</a> (rebrand, M17, 1.5.0) è accettato lo stesso giorno e va recepito nella stessa v1.7: <strong>tutto il testo proposto qui sotto usa la nomenclatura nuova</strong> (<em>Clarae notanda</em>, <code>clarae</code>, <code>.clarae/</code>). Dove cita il nome vecchio è perché parla dei dati o dei client della 1.x, o di un&#39;etichetta congelata (vedi §3).</p><p>Il testo proposto <strong>non</strong> dice nulla di Wails v3: <a href="./adr/0051-wails-v3.html">ADR-0051</a> non è accettato e lo spec continua a dire Wails v2 (D-07, A-03).</p><hr><h2 id="_1-riepilogo" tabindex="-1">1. Riepilogo <a class="header-anchor" href="#_1-riepilogo" aria-label="Permalink to &quot;1. Riepilogo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ADR</th><th>Cosa cambia nello spec</th><th>Sezioni</th></tr></thead><tbody><tr><td>0052</td><td>Nome del prodotto e identificatori in tutto lo spec, salvo le eccezioni del §3</td><td>intestazione, §1.1 … §4.5, C.2, C.4 (vedi §3)</td></tr><tr><td>0057</td><td>Il dispositivo desktop è identificato dal nome del computer: colonna <code>hostname</code>, indice unico parziale, registrazione come upsert (sempre <code>201</code>), revoca al logout</td><td>§1.7, §2.6.1, §3.2.2 (e l&#39;elenco delle migrazioni), §3.5.1</td></tr><tr><td>0058</td><td>Uscita completa: flusso di logout del desktop, <code>/signed-out</code> e <code>prompt=login</code>, post-logout redirect del client web</td><td>§1.3, §3.3.1</td></tr><tr><td>0059</td><td>Pulizia della cartella di configurazione legacy; lo ZIP ha la sola <code>.clarae/</code></td><td>§2.8.2, §3.4.6, §3.5.2</td></tr><tr><td>0060</td><td><code>features.web_viewer</code> <strong>acceso</strong> per default; «Nuova applicazione» nell&#39;esploratore</td><td>§2.2.1, §2.6.6, C.2, C.4</td></tr><tr><td>0061</td><td>Budget iniziale della console 720 kB</td><td>§4.4, C.4</td></tr></tbody></table><p>Più, per tutti: intestazione e registro delle revisioni (§2) e Appendice C.4 (§4.10).</p><hr><h2 id="_2-intestazione-e-registro-delle-revisioni" tabindex="-1">2. Intestazione e registro delle revisioni <a class="header-anchor" href="#_2-intestazione-e-registro-delle-revisioni" aria-label="Permalink to &quot;2. Intestazione e registro delle revisioni&quot;">​</a></h2><p><strong>Titolo (riga 1)</strong> e <strong>nome del prodotto (riga 9)</strong>: sono sostituzioni di ADR-0052 (vedi §3). Testo attuale della riga del nome:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| **Nome del prodotto** | *MemoBrain Notes* (identificatori `memobrain`; già &quot;Nodus&quot; come nome in codice) |</span></span></code></pre></div><p>Testo proposto:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| **Nome del prodotto** | *Clarae notanda* (identificatori `clarae`; già *MemoBrain Notes* e, come nome in codice, &quot;Nodus&quot;) |</span></span></code></pre></div><p><strong>Versione e data (righe 7-8).</strong> Testo attuale:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| **Versione documento** | 1.6 — Decisioni D-01…D-08 e ADR 0009–0022, 0024, 0026–0044 e 0053–0056 recepiti (vedi Appendice C) |</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| **Data** | 15 novembre 2026 |</span></span></code></pre></div><p>Testo proposto:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| **Versione documento** | 1.7 — Decisioni D-01…D-08 e ADR 0009–0022, 0024, 0026–0044 e 0052–0061 recepiti (vedi Appendice C) |</span></span>\n<span class="line"><span>| **Data** | 16 novembre 2026 |</span></span></code></pre></div><p><strong>Registro delle revisioni.</strong> Aggiungere in testa, prima della riga 1.6 (riga 17), la riga:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| 1.7 | 16 novembre 2026 | Recepiti gli ADR accettati dall&#39;owner il 16 novembre 2026 (Appendice C.4), già implementati (1.5.0 e 1.7.2): **ADR-0052** rebrand a *Clarae notanda* (identificatori `clarae`, cartella `.clarae/`, schema `clarae://`; restano congelate le etichette crittografiche `memobrain/v1/*` e `memobrain/v2/*`, e per i dati e i client della 1.x i nomi vecchi restano letti fino alla 2.0); **ADR-0057** identità del dispositivo desktop per nome del computer (colonna `devices.hostname` con indice unico parziale, registrazione come upsert sempre con `201`, revoca del proprio dispositivo al logout); **ADR-0058** logout completo da Keycloak (revoca dei token, logout back-channel del desktop, pagina `/signed-out` della console, `prompt=login` dopo un&#39;uscita esplicita); **ADR-0059** pulizia della cartella di configurazione legacy `.memobrain/` e ZIP con la sola `.clarae/` (emenda ADR-0052: non più «mai cancellazioni»); **ADR-0060** `features.web_viewer` **acceso per default** e «Nuova applicazione» nell&#39;esploratore dei file (emenda ADR-0056); **ADR-0061** budget iniziale della console a 720 kB (emenda ADR-0020). Sezioni modificate: il nome in tutto lo spec (ADR-0052), §1.3, §1.7, §2.2.1, §2.6.1, §2.6.6, §2.8.2, §3.2.2, §3.3.1, §3.4.6, §3.5.1, §3.5.2, §4.4, C.2, C.4. **Non** sono recepiti ADR-0023 (proposta) e gli ADR 0045–0051 (0045, 0046, 0047, 0048 e 0049 accettati; 0050 e 0051 in proposta): lo spec continua a dire Wails v2. |</span></span></code></pre></div><p>Le righe già presenti del registro (1.1–1.6) sono cronologia e <strong>non</strong> si riscrivono, anche se citano <code>.memobrain/</code>, <code>@memobrain/…</code> o «MemoBrain Notes». La riga 1.6 dice che lo spec «continua a dire Wails v2 e <em>MemoBrain Notes</em>… finché non sono recepiti»: resta com&#39;è, perché racconta la v1.6.</p><hr><h2 id="_3-recepimento-di-adr-0052-rebrand" tabindex="-1">3. Recepimento di ADR-0052 (rebrand) <a class="header-anchor" href="#_3-recepimento-di-adr-0052-rebrand" aria-label="Permalink to &quot;3. Recepimento di ADR-0052 (rebrand)&quot;">​</a></h2><p>La base è la sezione «Sostituzioni da riportare in <code>Specifications.md</code>» di <a href="./adr/0052-rebrand-clarae-notanda.html#sostituzioni-da-riportare-in-specificationsmd">ADR-0052</a>: lì stanno le tabelle «Sostituzione semplice» e «Non basta sostituire». <strong>I numeri di riga di quell&#39;elenco sono quelli della v1.5</strong>: la v1.6 ha aggiunto righe, quindi vanno ricalcolati. Il comando <code>command grep -n -i memobrain Specifications.md</code> dà 102 righe sulla v1.6.</p><h3 id="_3-1-cosa-deve-restare-con-il-nome-vecchio" tabindex="-1">3.1 Cosa deve restare con il nome vecchio <a class="header-anchor" href="#_3-1-cosa-deve-restare-con-il-nome-vecchio" aria-label="Permalink to &quot;3.1 Cosa deve restare con il nome vecchio&quot;">​</a></h3><p>Dopo il recepimento <code>grep -i memobrain</code> deve trovare solo queste righe (le stesse eccezioni di <code>scripts/rebrand/allowlist.tsv</code>, <code>task lint-brand</code>):</p><table tabindex="0"><thead><tr><th>Eccezione</th><th>Righe della v1.6 (da ricalcolare)</th><th>Perché</th></tr></thead><tbody><tr><td><strong>Etichette crittografiche congelate</strong> <code>memobrain/v1/*</code> e <code>memobrain/v2/*</code> (§3.8.2, §3.8.3)</td><td>1552–1554, 1563, 1587</td><td>Sono l&#39;input di HKDF e l&#39;AAD di AES-GCM: cambiarle rende indecifrabili i vault privati già creati. Aggiungere la nota «etichette di dominio congelate: il prefisso non segue il nome del prodotto» (ADR-0052, punto 2.1)</td></tr><tr><td><strong>Registro delle revisioni</strong> (righe 1.1–1.6)</td><td>17–21</td><td>Cronologia</td></tr><tr><td><strong>Righe di C.4</strong> (storico degli ADR già recepiti; l&#39;introduzione, riga 1986, si riscrive come in §4.10)</td><td>1986, 1994, 1996–1997, 1999, 2003–2004, 2008–2009, 2014, 2016, 2022, 2024</td><td>Storico: lasciarle com&#39;erano e aggiungere la nota di ADR-0052 (la riga nuova di C.4, §4.10)</td></tr><tr><td><strong>Dati e client della 1.x</strong> (periodo di compatibilità, fino alla 2.0)</td><td>dove il testo lo dice (cartella <code>.memobrain/</code>, schema <code>memobrain://</code>, <code>MEMOBRAIN_AUTH_REDIRECT</code>, <code>customData.memobrain</code>, proto <code>memobrain.v1</code>, realm, client e audience <code>memobrain…</code> delle installazioni create prima della 1.5, Web Lock <code>memobrain-workbench</code>)</td><td>Servono a descrivere il periodo di transizione di ADR-0052</td></tr></tbody></table><h3 id="_3-2-righe-che-non-sono-una-semplice-sostituzione" tabindex="-1">3.2 Righe che non sono una semplice sostituzione <a class="header-anchor" href="#_3-2-righe-che-non-sono-una-semplice-sostituzione" aria-label="Permalink to &quot;3.2 Righe che non sono una semplice sostituzione&quot;">​</a></h3><p>Seguire la tabella «Non basta sostituire» di ADR-0052. In sintesi, con le righe della v1.6:</p><table tabindex="0"><thead><tr><th>Punto</th><th>Righe della v1.6</th><th>Cosa scrivere</th></tr></thead><tbody><tr><td>Cartella <code>.memobrain/</code> → <code>.clarae/</code></td><td>300, 341–342, 353–355, 362, 483, 615, 618, 620–621, 632, 634, 670, 1089, 1172–1173, 1208, 1213–1216</td><td><code>.clarae/</code>, con il periodo di transizione: i client leggono anche <code>.memobrain/</code>; la parte locale si sposta all&#39;apertura, le impostazioni sincronizzate dei vault collegati con <code>features.config_dir_v2</code> (acceso dalla 1.7.0). Il titolo e la tabella di <strong>§3.4.6</strong> nominano entrambe le cartelle (vedi §4.6 per la parte di ADR-0059)</td></tr><tr><td>Temporanei <code>.memobrain-tmp-*</code></td><td>1089</td><td><code>.clarae-tmp-*</code>; i temporanei col vecchio nome restano esclusi (regola a doppio nome)</td></tr><tr><td>Schema URL, CLI</td><td>209–210, 373–374, 685, 1031, 1962</td><td><code>clarae://</code> registrato dagli installer; <code>memobrain://</code> ancora registrato e accettato; il redirect ha entrambi gli URI; CLI <code>clarae open</code>, <code>clarae new</code> (P2)</td></tr><tr><td><code>MEMOBRAIN_AUTH_REDIRECT</code></td><td>209</td><td><code>CLARAE_AUTH_REDIRECT</code> ha la precedenza; <code>MEMOBRAIN_AUTH_REDIRECT</code> vale ancora, con un avviso</td></tr><tr><td>Realm, client, audience, ruoli (§1.3, §1.6, §3.3.1)</td><td>187, 204, 209, 268, 646, 1031–1035</td><td><code>clarae…</code> per le installazioni nuove; su quelle esistenti vale il vecchio nome se l&#39;issuer è <code>/realms/memobrain</code> (famiglia dell&#39;issuer, <code>docs/admin-guide/configurazione.md</code>)</td></tr><tr><td>gRPC (§3.6)</td><td>1481</td><td><code>package clarae.v1;</code>, con la nota: <code>memobrain.v1</code> è servito ancora dallo stesso handler</td></tr><tr><td>Chiave Excalidraw (§2.7)</td><td>615, 632</td><td><code>customData.clarae</code>; i client leggono anche <code>customData.memobrain</code></td></tr><tr><td>Web Lock del workbench (§1.7)</td><td>285</td><td><code>clarae-workbench</code>; la scheda nuova prende anche il lock vecchio</td></tr><tr><td>Feature flag <code>features.config_dir_v2</code> (§2.6.6)</td><td>tabella dei flag</td><td>Riga nuova, vedi §3.3</td></tr></tbody></table><h3 id="_3-3-riga-nuova-nella-tabella-dei-flag-§2-6-6" tabindex="-1">3.3 Riga nuova nella tabella dei flag (§2.6.6) <a class="header-anchor" href="#_3-3-riga-nuova-nella-tabella-dei-flag-§2-6-6" aria-label="Permalink to &quot;3.3 Riga nuova nella tabella dei flag (§2.6.6)&quot;">​</a></h3><p>Il flag <code>features.config_dir_v2</code> non è nello spec v1.6 e ADR-0059 ne dipende (la parte sincronizzata della pulizia vale solo con il flag acceso). Aggiungere dopo la riga di <code>features.web_viewer</code> (riga 591):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| `features.config_dir_v2` | **acceso dalla 1.7.0** | Sposta le impostazioni sincronizzate dei vault collegati dalla cartella di configurazione della 1.x (`.memobrain/`) a `.clarae/`, come uno spostamento ordinario che conserva gli id dei file e lo storico (ADR-0052). Un client 1.4 o precedente legge e scrive ancora la cartella vecchia e ricreerebbe ogni impostazione: si aggiornano prima i dispositivi, poi il cloud, oppure lo si imposta a `false` nel frattempo. Spento ferma solo lo spostamento (un&#39;impostazione già spostata resta dov&#39;è e il client legge entrambe le cartelle). Un cloud 1.5 o 1.6 distribuisce `false`, uno 1.7 `true`; la pulizia sincronizzata di ADR-0059 richiede un cloud 1.7 o successivo |</span></span></code></pre></div><p>Fonte: <code>api/config-profile.schema.json</code> (<code>features.config_dir_v2</code>, default <code>true</code>).</p><h3 id="_3-4-un-avvertenza-sul-testo-gia-nello-spec" tabindex="-1">3.4 Un&#39;avvertenza sul testo già nello spec <a class="header-anchor" href="#_3-4-un-avvertenza-sul-testo-gia-nello-spec" aria-label="Permalink to &quot;3.4 Un&#39;avvertenza sul testo già nello spec&quot;">​</a></h3><p>Il testo aggiunto dalle revisioni 1.3–1.6 usa <code>memobrain</code> e <code>.memobrain/</code> dove descrive il comportamento di allora. Il recepimento di ADR-0052 sostituisce il nome anche lì (è nelle righe delle liste di §3.2), <strong>tranne</strong> dove il testo descrive un file o un client della 1.x.</p><hr><h2 id="_4-modifiche-per-sezione" tabindex="-1">4. Modifiche per sezione <a class="header-anchor" href="#_4-modifiche-per-sezione" aria-label="Permalink to &quot;4. Modifiche per sezione&quot;">​</a></h2><p>Nelle citazioni qui sotto, il testo attuale è quello della v1.6 <strong>con il nome vecchio</strong>, come sta oggi nello spec; il testo proposto è già con la nomenclatura nuova.</p><h3 id="_4-1-adr-0057-—-§1-7-«workbench-web-e-core-del-client-in-webassembly»" tabindex="-1">4.1 ADR-0057 — §1.7 «Workbench web e core del client in WebAssembly» <a class="header-anchor" href="#_4-1-adr-0057-—-§1-7-«workbench-web-e-core-del-client-in-webassembly»" aria-label="Permalink to &quot;4.1 ADR-0057 — §1.7 «Workbench web e core del client in WebAssembly»&quot;">​</a></h3><p>Il §1.7 contiene i due punti sull&#39;identità e sulla revoca dei dispositivi. Il titolo della sezione non cambia.</p><p><strong>(a) Riga 287, punto «Dispositivo revocato».</strong> Testo attuale (frammento):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>offre &quot;Registra di nuovo questo dispositivo&quot;, che registra un nuovo dispositivo dello stesso account e invia ciò che era in attesa.</span></span></code></pre></div><p>Testo proposto (sostituisce il frammento):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>offre &quot;Registra di nuovo questo dispositivo&quot;, che registra il dispositivo dello stesso account (sul desktop riattiva la riga dello stesso nome del computer, sul browser ne crea una nuova) e invia ciò che era in attesa. Il client **non** ripete da solo la registrazione: una revoca fatta dalla console non si annulla dal computer stesso al primo `commit` rifiutato (ADR-0057).</span></span></code></pre></div><p><strong>(b) Aggiunta.</strong> Dopo il punto «Dispositivo revocato» (riga 287) aggiungere:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- **Identità del dispositivo desktop (ADR-0057).** Il client desktop si registra con il nome del computer (`os.Hostname()`, oppure la variabile d&#39;ambiente `CLARAE_DEVICE_NAME`, che serve a due istanze sullo stesso computer e ai test). Per `windows`, `macos` e `linux` il cloud identifica il dispositivo da `(utente, piattaforma, nome senza maiuscole né spazi ai lati)`: registrare di nuovo lo stesso nome e la stessa piattaforma (il login successivo a un logout, o &quot;Registra di nuovo questo dispositivo&quot;) restituisce lo stesso `id`, riattivato se era revocato, e non aggiunge righe all&#39;elenco (`POST /me/devices`, §3.5.1). Al logout il client revoca il proprio dispositivo (§1.3), a miglior sforzo: senza rete la riga resta attiva e il login successivo la riprende. **Limiti accettati:** due computer dello stesso utente con lo stesso nome e la stessa piattaforma sono un solo dispositivo (condividono `id` e ultimo accesso, e una revoca vale per entrambi); un computer rinominato compare come dispositivo nuovo e il vecchio resta attivo finché non lo si revoca; **una revoca dalla console si annulla al login successivo della stessa macchina**, perché la registrazione riattiva la riga: vale quindi per un computer che non rientra con lo stesso nome, e per escludere un utente restano la sospensione dell&#39;account e la revoca delle sessioni (§2.6.5). Il browser (`web`) non cambia: un dispositivo per profilo, con l&#39;identità in IndexedDB.</span></span></code></pre></div><h3 id="_4-2-adr-0057-—-§2-6-1-«gestione-vault»" tabindex="-1">4.2 ADR-0057 — §2.6.1 «Gestione vault» <a class="header-anchor" href="#_4-2-adr-0057-—-§2-6-1-«gestione-vault»" aria-label="Permalink to &quot;4.2 ADR-0057 — §2.6.1 «Gestione vault»&quot;">​</a></h3><p>Riga 537. Testo attuale (frammento):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nome, piattaforma (`platform: &quot;web&quot;` per il workbench web, uno per profilo del browser, §1.7), ultimo accesso;</span></span></code></pre></div><p>Testo proposto (sostituisce il frammento):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nome (per `windows`, `macos` e `linux` è il nome del computer e identifica il dispositivo: uno per utente, piattaforma e nome, anche dopo un logout, §1.7, ADR-0057), piattaforma (`platform: &quot;web&quot;` per il workbench web, uno per profilo del browser, §1.7), ultimo accesso;</span></span></code></pre></div><h3 id="_4-3-adr-0057-—-§3-2-2-«ddl-di-riferimento»" tabindex="-1">4.3 ADR-0057 — §3.2.2 «DDL di riferimento» <a class="header-anchor" href="#_4-3-adr-0057-—-§3-2-2-«ddl-di-riferimento»" aria-label="Permalink to &quot;4.3 ADR-0057 — §3.2.2 «DDL di riferimento»&quot;">​</a></h3><p><strong>(a) Tabella <code>devices</code></strong> (dalla riga 814, 10 righe). Testo attuale:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CREATE TABLE devices (</span></span>\n<span class="line"><span>  id           UUID PRIMARY KEY,</span></span>\n<span class="line"><span>  user_id      UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,</span></span>\n<span class="line"><span>  name         TEXT NOT NULL,</span></span>\n<span class="line"><span>  platform     TEXT NOT NULL,</span></span>\n<span class="line"><span>  app_version  TEXT,</span></span>\n<span class="line"><span>  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),</span></span>\n<span class="line"><span>  last_seen_at TIMESTAMPTZ,</span></span>\n<span class="line"><span>  revoked_at   TIMESTAMPTZ</span></span>\n<span class="line"><span>);</span></span></code></pre></div><p>Testo proposto:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CREATE TABLE devices (</span></span>\n<span class="line"><span>  id           UUID PRIMARY KEY,</span></span>\n<span class="line"><span>  user_id      UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,</span></span>\n<span class="line"><span>  name         TEXT NOT NULL,</span></span>\n<span class="line"><span>  platform     TEXT NOT NULL,</span></span>\n<span class="line"><span>  app_version  TEXT,</span></span>\n<span class="line"><span>  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),</span></span>\n<span class="line"><span>  last_seen_at TIMESTAMPTZ,</span></span>\n<span class="line"><span>  revoked_at   TIMESTAMPTZ,</span></span>\n<span class="line"><span>  hostname     TEXT                         -- solo desktop: lower(btrim(name)); NULL per `web` e per le righe che hanno perso l&#39;identità del loro computer (migrazione 0016, ADR-0057)</span></span>\n<span class="line"><span>);</span></span>\n<span class="line"><span>CREATE UNIQUE INDEX devices_hostname_uq ON devices (user_id, platform, hostname) WHERE hostname IS NOT NULL;  -- un dispositivo desktop per utente, piattaforma e nome</span></span></code></pre></div><p><strong>(b) Elenco delle migrazioni</strong> (riga 1020). Testo attuale (due frammenti):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- **Migrazioni (ADR-0009, ADR-0011, ADR-0012, ADR-0021).**</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>`0008_role_changed_at`, `0009_upload_chunk_keys`.</span></span></code></pre></div><p>Testo proposto (sostituiscono i due frammenti):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- **Migrazioni (ADR-0009, ADR-0011, ADR-0012, ADR-0021, ADR-0057).**</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>`0008_role_changed_at`, `0009_upload_chunk_keys`, `0016_device_hostname` (colonna `devices.hostname`; per ogni `(utente, piattaforma, nome)` resta attivo il dispositivo con l&#39;attività più recente, gli altri si **revocano** e perdono il nome, ma le righe non si cancellano perché le revisioni dei file puntano a `device_id`; indice unico parziale `devices_hostname_uq`; ADR-0057). Le migrazioni `0010`–`0015` non sono descritte in questo elenco.</span></span></code></pre></div><h3 id="_4-4-adr-0057-—-§3-5-1-«profilo-dispositivi-configurazione»" tabindex="-1">4.4 ADR-0057 — §3.5.1 «Profilo, dispositivi, configurazione» <a class="header-anchor" href="#_4-4-adr-0057-—-§3-5-1-«profilo-dispositivi-configurazione»" aria-label="Permalink to &quot;4.4 ADR-0057 — §3.5.1 «Profilo, dispositivi, configurazione»&quot;">​</a></h3><p><strong>Riga 1265.</strong> Testo attuale:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| POST | `/me/devices` | U | Registra dispositivo (ritorna `device_id`; `platform: &quot;web&quot;` per il workbench web, §1.7) |</span></span></code></pre></div><p>Testo proposto:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| POST | `/me/devices` | U | Registra dispositivo (ritorna `device_id`; `platform: &quot;web&quot;` per il workbench web, §1.7). Per `windows`, `macos` e `linux` `name` è il nome del computer e identifica il dispositivo: lo stesso nome e la stessa piattaforma restituiscono lo stesso `id`, riattivato se era revocato, con nome e `app_version` aggiornati; per `web` ogni registrazione crea un dispositivo. La risposta è sempre `201` (ADR-0057) |</span></span></code></pre></div><p><strong>Riga 1266.</strong> Testo attuale:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| DELETE | `/me/devices/{id}` | U | Revoca dispositivo; il `commit` successivo di quel dispositivo risponde `403 FORBIDDEN` con `extra.reason = &quot;device_revoked&quot;` (§1.7) |</span></span></code></pre></div><p>Testo proposto:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| DELETE | `/me/devices/{id}` | U | Revoca dispositivo; il `commit` successivo di quel dispositivo risponde `403 FORBIDDEN` con `extra.reason = &quot;device_revoked&quot;` (§1.7). Il client desktop lo chiama sul proprio dispositivo al logout (§1.3, ADR-0057) |</span></span></code></pre></div><h3 id="_4-5-adr-0058-—-§1-3-e-§3-3-1" tabindex="-1">4.5 ADR-0058 — §1.3 e §3.3.1 <a class="header-anchor" href="#_4-5-adr-0058-—-§1-3-e-§3-3-1" aria-label="Permalink to &quot;4.5 ADR-0058 — §1.3 e §3.3.1&quot;">​</a></h3><p><strong>(a) §1.3 «Flusso di autenticazione (client desktop)».</strong> Il flusso del login non cambia. Dopo l&#39;ultimo punto di «Regole chiave» (riga 211) aggiungere:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- **Uscita (ADR-0058).** «Esci» non lascia sessioni vive. *Client desktop*, in quest&#39;ordine e a miglior sforzo (un errore si scrive nel log e l&#39;uscita prosegue; i passi di rete hanno un tetto comune di 8 s): ferma la sync; revoca il proprio dispositivo sul cloud (`DELETE /me/devices/{id}`, §3.5.1, ADR-0057) finché il token è valido; chiude la sessione dell&#39;identity provider con una `POST` back-channel sull&#39;`end_session_endpoint` della discovery (`client_id` e refresh token, senza browser né `id_token_hint`) e poi revoca il refresh token dal `revocation_endpoint` (se la discovery non lo annuncia, l&#39;URL di Keycloak derivato dall&#39;issuer, `&lt;issuer&gt;/protocol/openid-connect/revoke`); scrive il marcatore `auth-logged-out` nella cartella dati dell&#39;app (fuori dal vault, non sincronizzato) e cancella la sessione locale. Il login successivo aggiunge `prompt=login` all&#39;URL di autorizzazione, così Keycloak chiede le credenziali anche se una sessione SSO è sopravvissuta (un broker, un realm vecchio), e cancella il marcatore. Una sessione ospitata (il core nel browser) non esegue nulla di questo: i token sono della pagina. *Console web e workbench* (stessa sessione della pagina): `signOut` revoca i token (a miglior sforzo), chiama `signoutRedirect` con `id_token_hint`, `client_id` e `post_logout_redirect_uri = &lt;origine&gt;/signed-out`, e scrive in `localStorage` il marcatore `clarae.auth.forceLogin`, che fa passare `prompt=login` al `signIn` successivo; `/signed-out` è una pagina pubblica («Sei uscito da Clarae notanda», con il pulsante «Accedi») che **non** avvia l&#39;accesso da sola. Un accesso che non segue un&#39;uscita esplicita (scadenza della sessione, primo accesso) non forza il prompt. **Limite:** il logout back-channel dipende dal comportamento di Keycloak 26 e non è ancora provato su un Keycloak vero (le prove automatiche usano un server OIDC finto); su un identity provider diverso la chiamata può fallire senza effetti, e `prompt=login` copre la sessione residua.</span></span></code></pre></div><p><strong>(b) §3.3.1 «Configurazione Keycloak»</strong>, tabella. Riga 1031, frammento attuale:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scope `openid profile email offline_access`</span></span></code></pre></div><p>Testo proposto (sostituisce il frammento):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scope `openid profile email offline_access`, post-logout redirect URI `clarae://auth/logout` (`memobrain://auth/logout` per la 1.x) e `http://127.0.0.1/*` (il logout del desktop è back-channel e non apre il browser, §1.3, ADR-0058)</span></span></code></pre></div><p>Riga 1032, frammento attuale:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>redirect `https://&lt;host&gt;/*`, Web Origins = host</span></span></code></pre></div><p>Testo proposto (sostituisce il frammento):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>redirect `https://&lt;host&gt;/*`, **post-logout redirect URI** `https://&lt;host&gt;/*` (la console esce su `https://&lt;host&gt;/signed-out`, ADR-0058), Web Origins = host</span></span></code></pre></div><p>Aggiungere dopo la tabella (dopo la riga «Sicurezza», riga 1037):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>**Realm già importato (ADR-0058).** Il file del realm si importa con `--import-realm`, che **non sovrascrive** un realm esistente: su un&#39;installazione esistente le modifiche al file non hanno effetto. `post.logout.redirect.uris` del client web si controlla dalla console di Keycloak e deve ammettere `&lt;origine&gt;/signed-out`; altrimenti Keycloak risponde con l&#39;errore «URI di redirect non valido» al logout e non chiude la sessione SSO (guida di amministrazione, sezione Keycloak).</span></span></code></pre></div><h3 id="_4-6-adr-0059-—-§2-8-2-§3-4-6-§3-5-2" tabindex="-1">4.6 ADR-0059 — §2.8.2, §3.4.6, §3.5.2 <a class="header-anchor" href="#_4-6-adr-0059-—-§2-8-2-§3-4-6-§3-5-2" aria-label="Permalink to &quot;4.6 ADR-0059 — §2.8.2, §3.4.6, §3.5.2&quot;">​</a></h3><p><strong>(a) §2.8.2 «Vista Utente standard», riga «Download ZIP»</strong> (riga 670). Primo frammento attuale:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(path originali, escluse le parti di `.memobrain/` specifiche del dispositivo)</span></span></code></pre></div><p>Testo proposto (sostituisce il frammento):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(path originali, escluse le parti di `.clarae/` specifiche del dispositivo; i file della cartella di configurazione della 1.x, `.memobrain/`, escono sotto `.clarae/` e, se lo stesso nome esiste in entrambe, vince `.clarae/`: lo ZIP ha una sola cartella di configurazione, ADR-0059)</span></span></code></pre></div><p>Secondo frammento attuale (stessa riga, lo ZIP dei vault privati):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>per ogni file si verifica lo SHA-256 del cifrato e i percorsi non sicuri o i blob corrotti sono saltati e riportati.</span></span></code></pre></div><p>Testo proposto (sostituisce il frammento):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>per ogni file si verifica lo SHA-256 del cifrato e i percorsi non sicuri o i blob corrotti sono saltati e riportati. La stessa riscrittura dei path `.memobrain/…` in `.clarae/…` vale nel browser (`archivePath` in `packages/vaultcrypto-web/src/configdir.ts`): la voce `.memobrain/` che ha la gemella in `.clarae/` non entra nell&#39;archivio, qualunque sia l&#39;ordine del manifest, e nel rapporto compare come `duplicate_path` (ADR-0059).</span></span></code></pre></div><p><strong>(b) §3.4.6 «Scope di sincronizzazione della cartella <code>.clarae/</code>»</strong> (titolo e tabella: sostituzioni di ADR-0052, vedi §3.2; la tabella nomina entrambe le cartelle durante la transizione). Aggiungere dopo la tabella e prima di «**Chiavi di <code>graph.json</code>»:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>**Pulizia della cartella legacy (ADR-0059).** Un vault passato per la 1.x può avere due cartelle di configurazione, `.clarae/` e `.memobrain/`. All&#39;apertura del vault, **una volta per versione dell&#39;app** (marcatore locale `.clarae/cache/legacy-config-cleanup`, che sta in `cache/` e quindi non si sincronizza), il client ripulisce la cartella vecchia: cancella le voci solo locali (`index.db*`, `sync.db*`, `workspace*.json`, `cache/`) che `.clarae/` ha già (`sync.db*` solo se il database aperto è quello di `.clarae/`); sposta in `.clarae/snapshots/` gli snapshot senza collisione e cancella quelli identici, mentre quelli diversi restano dove sono (sono l&#39;unica copia di quella versione); per un vault non collegato cancella le impostazioni identiche a quelle di `.clarae/` e manda nel cestino del vault (`.trash/`) quelle diverse; toglie i file spazzatura del sistema (`.DS_Store`, `Thumbs.db`, `desktop.ini`) e le cartelle rimaste vuote, `.memobrain/` compresa. Non tocca i link simbolici né ciò che esiste solo nella cartella vecchia. **Vault collegato:** le impostazioni sincronizzate ancora in `.memobrain/` le gestisce la sync: se `.clarae/&lt;nome&gt;` esiste già e le due righe sono pulite (sincronizzate, senza modifiche locali, tentativi, errori o conflitti), il motore toglie il file legacy dal disco (cancellato se identico a quello corrente, nel cestino del vault se diverso) e invia una normale **operazione di cancellazione con `base_rev`**: la revisione resta nello storico del cloud, quindi nessuna perdita silenziosa (D-04, §3.4.5). Al massimo 64 file per passata, insieme agli spostamenti. Vale solo con `features.config_dir_v2` acceso, cioè contro un cloud 1.7 o successivo (§2.6.6): con un cloud 1.5 o 1.6 la parte sincronizzata non si corregge. **Limiti:** un dispositivo 1.4 o precedente rimasto sul vault ricrea le impostazioni che non trova nella cartella vecchia (due copie con id diversi, da riconciliare a mano), quindi si aggiornano prima i dispositivi e poi il cloud; un client che esegue la pulizia prima dell&#39;aggiornamento del cloud la rifà alla versione successiva. La pulizia sostituisce la regola «mai cancellazioni» della fase 1 di ADR-0052: cancella solo ciò che `.clarae/` ha già o che è un duplicato, e nessun dato che esiste in una sola copia viene eliminato. Il doppio nome e la pulizia si tolgono insieme con la 2.0.</span></span></code></pre></div><p><strong>(c) §3.5.2 «Vault e storico»</strong>, due righe dell&#39;export. Frammento attuale della riga <code>…/exports/{eid}/download</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ZIP di un job pronto (valido 24 h) |</span></span></code></pre></div><p>Testo proposto:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ZIP di un job pronto (valido 24 h); i path della cartella di configurazione della 1.x escono sotto `.clarae/` (§2.8.2, ADR-0059) |</span></span></code></pre></div><p>Frammento attuale della riga <code>…/export.zip</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ZIP in streaming (vault condivisi fino a 512 MB, oltre `409 INVALID_STATE`: serve un job; `409 VAULT_ENCRYPTED` per i privati) |</span></span></code></pre></div><p>Testo proposto:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ZIP in streaming (vault condivisi fino a 512 MB, oltre `409 INVALID_STATE`: serve un job; `409 VAULT_ENCRYPTED` per i privati); stessa riscrittura dei path di `.memobrain/` in `.clarae/` (§2.8.2, ADR-0059) |</span></span></code></pre></div><h3 id="_4-7-adr-0060-—-§2-2-1-§2-6-6-c-2" tabindex="-1">4.7 ADR-0060 — §2.2.1, §2.6.6, C.2 <a class="header-anchor" href="#_4-7-adr-0060-—-§2-2-1-§2-6-6-c-2" aria-label="Permalink to &quot;4.7 ADR-0060 — §2.2.1, §2.6.6, C.2&quot;">​</a></h3><p><strong>(a) §2.2.1 «Matrice di parità», riga «Web viewer»</strong> (riga 367). Frammento attuale (fine della cella):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Dietro `features.web_viewer`, **spento per default** (§2.6.6) |</span></span></code></pre></div><p>Testo proposto (sostituisce il frammento):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Dietro `features.web_viewer`, **acceso per default dalla 1.7.2** (§2.6.6, ADR-0060): un profilo può spegnerlo. **Esploratore dei file:** un pulsante «Nuova applicazione» nella barra degli strumenti e la stessa voce nei due menu contestuali (su un elemento e sulla zona vuota) creano il file `.webapp` nella cartella selezionata, o nella radice se non c&#39;è una selezione; compaiono solo con il flag acceso e su un vault non in sola lettura. L&#39;esploratore e le schede mostrano il nome senza `.webapp`. Fuori da macOS, e nel workbench web, la scheda è un riquadro con «Apri nel browser» |</span></span></code></pre></div><p><strong>(b) §2.6.6, tabella dei flag</strong>, riga di <code>features.web_viewer</code> (riga 591). Primo frammento attuale:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| `features.web_viewer` | spento |</span></span></code></pre></div><p>Testo proposto:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| `features.web_viewer` | **acceso dalla 1.7.2** |</span></span></code></pre></div><p>Secondo frammento attuale (fine della cella):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Resta spento per default finché la matrice manuale di prove sulla finestra reale non è eseguita |</span></span></code></pre></div><p>Testo proposto (sostituisce il frammento):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Fino alla 1.7.1 era spento per default; dalla 1.7.2 è **acceso** (decisione dell&#39;owner, ADR-0060), perché una funzione spenta era invisibile a chi non amministra il cloud. La matrice manuale di prove sulla finestra reale (`docs/qa/m18-webview-matrice.md`) **non è ancora eseguita**: chi non vuole le applicazioni le spegne dal profilo, globale o di gruppo (`{&quot;features&quot;: {&quot;web_viewer&quot;: false}}`). Un profilo che ha già `false` esplicito lo conserva; un client che non ha ancora letto un profilo usa il default di prodotto (acceso), quindi le applicazioni compaiono anche prima dell&#39;accesso al cloud. Le misure di sicurezza di ADR-0056 non dipendono dal flag |</span></span></code></pre></div><p>Fonte: <code>api/config-profile.schema.json</code> (<code>features.web_viewer</code>, <code>&quot;default&quot;: true</code>).</p><p><strong>(c) Appendice C.2 «Rischi tecnici»</strong>, riga «Web viewer in iframe…» (riga 1954). Frammento attuale:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Funzione dietro `features.web_viewer`, spento di default |</span></span></code></pre></div><p>Testo proposto (sostituisce il frammento):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Funzione dietro `features.web_viewer`, acceso di default dalla 1.7.2 (ADR-0060): la matrice manuale di prove sulla finestra reale non è ancora eseguita, e il flag si spegne dal profilo |</span></span></code></pre></div><h3 id="_4-8-adr-0061-—-§4-4-«web-ui»" tabindex="-1">4.8 ADR-0061 — §4.4 «Web UI» <a class="header-anchor" href="#_4-8-adr-0061-—-§4-4-«web-ui»" aria-label="Permalink to &quot;4.8 ADR-0061 — §4.4 «Web UI»&quot;">​</a></h3><p>Riga 1870. Frammento attuale:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>console iniziale ≤ 700 kB e totale ≤ 1000 kB</span></span></code></pre></div><p>Testo proposto (sostituisce il frammento):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>console iniziale ≤ 720 kB (700 kB fino alla 1.7.1, ADR-0061) e totale ≤ 1000 kB</span></span></code></pre></div><p>La console resta un file unico coperto da SRI (<code>splitting: false</code>): il limite alzato è per le funzioni di M21 (pagina «Sei uscito», logout completo, tooltip della quota, gemelle legacy nello ZIP privato); la console pesa 701 kB.</p><h3 id="_4-9-voci-senza-adr-a-scelta-dell-owner" tabindex="-1">4.9 Voci senza ADR (a scelta dell&#39;owner) <a class="header-anchor" href="#_4-9-voci-senza-adr-a-scelta-dell-owner" aria-label="Permalink to &quot;4.9 Voci senza ADR (a scelta dell&#39;owner)&quot;">​</a></h3><p>La 1.7.2 contiene anche l&#39;Onda F di M21 (registro di audit, <a href="./roadmap.html">roadmap</a> §13-quaterdecies), <strong>senza un ADR</strong>: nessun accettato la copre, quindi non è una deviazione dallo spec. Lo spec documenta le variabili d&#39;ambiente del servizio in §1.6 (<code>SHUTDOWN_DRAIN</code>, <code>TRUSTED_PROXIES</code>), quindi si propone, <strong>se l&#39;owner lo ritiene utile</strong>, questo paragrafo dopo «Spegnimento e repliche (ADR-0022)» (§1.6):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>**Aggiornamento senza perdere il database.** Con `DB_EXPECT_INITIALIZED=true` i ruoli `api` e `all` che trovano il database vuoto (nessuna migrazione applicata) non creano lo schema e terminano con un errore, invece di avviarsi su un database nuovo senza dati né registro di audit. Il chart Helm lo imposta a ogni `helm upgrade` (`.Release.IsUpgrade`), a meno che `config` non lo contenga già; con Compose si imposta in `.env` dopo il primo avvio. All&#39;avvio dei ruoli `api` e `all`, dopo le migrazioni, il servizio scrive nel log una riga `database state` con la versione dello schema, il numero di righe di `audit_log` e la data della prima. Nessuna migrazione cancella `audit_log`: un test sulle migrazioni lo verifica sulle sezioni `+goose Up` (`services/cloud/internal/db/audit_migrations_test.go`).</span></span></code></pre></div><p>Fonti: <code>services/cloud/internal/config/config.go</code> (<code>ExpectInitialized</code>), <code>deploy/helm/clarae/templates/configmap.yaml</code>, <code>services/cloud/cmd/clarae-cloud/main.go</code> (<code>database state</code>), <code>docs/admin-guide/configurazione.md</code>.</p><h3 id="_4-10-appendice-c-4-«adr-recepiti»" tabindex="-1">4.10 Appendice C.4 «ADR recepiti» <a class="header-anchor" href="#_4-10-appendice-c-4-«adr-recepiti»" aria-label="Permalink to &quot;4.10 Appendice C.4 «ADR recepiti»&quot;">​</a></h3><p><strong>(a) Introduzione</strong> (riga 1986). Primo frammento attuale:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0053–0056 nella v1.6, già implementati, in 1.6.0, 1.7.0 e 1.7.1)</span></span></code></pre></div><p>Testo proposto (sostituisce il frammento):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0053–0056 nella v1.6, già implementati, in 1.6.0, 1.7.0 e 1.7.1; 0052 e 0057–0061 nella v1.7, già implementati, in 1.5.0 e 1.7.2)</span></span></code></pre></div><p>Secondo frammento attuale (fine della riga):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>e gli ADR 0045–0052, posteriori alla v1.5 e non toccati da questa revisione (0045, 0046, 0047, 0048 e 0049 accettati; 0050, 0051 e 0052 in stato *proposta*). Per questo lo spec dice ancora Wails v2 e *MemoBrain Notes* (identificatori `memobrain`, cartella `.memobrain/`): il testo aggiunto dalla v1.6 segue la nomenclatura dello spec, mentre nel codice i nomi sono *Clarae notanda* e `.clarae/` (ADR-0052).</span></span></code></pre></div><p>Testo proposto (sostituisce il frammento):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>e gli ADR 0045–0051, posteriori alla v1.5 e non toccati dalle revisioni 1.6 e 1.7 (0045, 0046, 0047, 0048 e 0049 accettati; 0050 e 0051 in stato *proposta*). Per questo lo spec dice ancora Wails v2 (ADR-0051 non è recepito). I nomi sono quelli di ADR-0052: *Clarae notanda*, identificatori `clarae`, cartella `.clarae/`, con le sole eccezioni che l&#39;ADR elenca (etichette crittografiche congelate `memobrain/v1/*` e `memobrain/v2/*`; dati e client della 1.x). ADR-0059 emenda ADR-0052 (la cartella `.memobrain/` si ripulisce dopo l&#39;aggiornamento), ADR-0060 emenda ADR-0056 (`features.web_viewer` acceso per default) e ADR-0061 emenda ADR-0020 (budget iniziale della console 720 kB): valgono i più recenti.</span></span></code></pre></div><p><strong>(b) Righe da modificare.</strong> Riga di ADR-0056 (riga 2027), frammento attuale:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>`features.web_viewer` **spento di default**.</span></span></code></pre></div><p>Testo proposto (sostituisce il frammento):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>`features.web_viewer` **spento di default** nella 1.7.0 e nella 1.7.1, **acceso dalla 1.7.2** (ADR-0060).</span></span></code></pre></div><p>Riga di ADR-0020 (riga 2001), frammento attuale:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(console 700/1000 kB,</span></span></code></pre></div><p>Testo proposto (sostituisce il frammento):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(console 720/1000 kB, 700/1000 fino alla 1.7.1 per ADR-0061,</span></span></code></pre></div><p><strong>(c) Righe nuove</strong>, in fondo alla tabella, dopo la riga di ADR-0056 (ultima riga dello spec). Le colonne sono: ADR, Tema, Decisione, Recepito in.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| ADR-0052 | Rebrand | Il prodotto si chiama *Clarae notanda* (identificatori `clarae`): scope `@clarae/*`, binari `clarae-core` e `clarae-cloud`, cartella di configurazione `.clarae/` (e `.clarae-tmp-*`), schema `clarae://`, package gRPC `clarae.v1`, chiave `customData.clarae` dei disegni, Web Lock `clarae-workbench`, flag `features.config_dir_v2`; realm, client e audience `clarae…` per le installazioni nuove. **Congelate** le etichette crittografiche `memobrain/v1/*` e `memobrain/v2/*` (cambiarle rende indecifrabili i vault privati). Per i dati e i client della 1.x restano letti i nomi vecchi (cartella `.memobrain/`, schema `memobrain://`, `customData.memobrain`, proto `memobrain.v1`, realm e audience delle installazioni esistenti) fino alla 2.0; migrazione automatica della cartella dati, dello storage del browser e del keychain; emendato da ADR-0059 (v1.7) | Intestazione, §1.3, §1.6, §1.7, §2.1, §2.5, §2.6.6, §2.7, §3.3.1, §3.4.2, §3.4.5, §3.4.6, §3.6, §3.8 (etichette invariate), §4, C.2, C.4 |</span></span>\n<span class="line"><span>| ADR-0057 | Identità del dispositivo desktop | Un dispositivo desktop è identificato da `(utente, piattaforma, nome del computer)`: colonna `devices.hostname` (`lower(btrim(name))`, NULL per `web`) e indice unico parziale (migrazione `0016`, che revoca i duplicati senza cancellare righe); `POST /me/devices` per `windows`, `macos` e `linux` è un upsert che restituisce lo stesso `id`, riattivato se revocato, sempre con `201`; il logout del desktop revoca il proprio dispositivo (a miglior sforzo, dopo aver fermato la sync); `CLARAE_DEVICE_NAME` sostituisce il nome del computer; nessuna nuova registrazione automatica dopo una revoca dalla console. Limiti: due computer con lo stesso nome e piattaforma sono un solo dispositivo, e una revoca dalla console si annulla al login successivo della stessa macchina (v1.7) | §1.7, §2.6.1, §3.2.2, §3.5.1 |</span></span>\n<span class="line"><span>| ADR-0058 | Logout completo da Keycloak | Console e workbench: `signOut` revoca i token, passa `id_token_hint`, `client_id` e `post_logout_redirect_uri = &lt;origine&gt;/signed-out`; pagina pubblica `/signed-out` senza login automatico; `prompt=login` al primo accesso dopo un&#39;uscita esplicita (marcatore `clarae.auth.forceLogin` in `localStorage`). Desktop: logout back-channel sull&#39;`end_session_endpoint` della discovery, poi revoca dal `revocation_endpoint` (ripiego sull&#39;URL di Keycloak), marcatore `auth-logged-out` e `prompt=login` al login successivo; passi di rete con tetto di 8 s e a miglior sforzo. Un realm già importato non cambia da solo: `post.logout.redirect.uris` si controlla dalla console di Keycloak. Non provato su un Keycloak vero; la causa del rientro senza password su E2BR non è accertata (v1.7) | §1.3, §3.3.1 |</span></span>\n<span class="line"><span>| ADR-0059 | Cartella di configurazione legacy | `vaultdir.CleanupLegacy` ripulisce `.memobrain/` all&#39;apertura del vault, una volta per versione (voci locali già presenti in `.clarae/`, snapshot identici, impostazioni identiche; le diverse nel cestino del vault); per i vault collegati il motore di sync cancella la riga legacy con una normale operazione di cancellazione con `base_rev` (solo con `features.config_dir_v2` acceso, cioè con un cloud 1.7 o successivo); lo ZIP del server e quello del browser riscrivono `.memobrain/…` in `.clarae/…` e, in caso di collisione, vince `.clarae/`. Emenda ADR-0052 («mai cancellazioni») (v1.7) | §2.8.2, §3.4.6, §3.5.2 |</span></span>\n<span class="line"><span>| ADR-0060 | Web viewer acceso di default | `features.web_viewer` ha default `true` nello schema del Config Profile (un profilo può spegnerlo); pulsante e voce di menu «Nuova applicazione» nell&#39;esploratore dei file, e nomi senza `.webapp` in esploratore e schede; la vista incorporata resta solo su macOS. La matrice manuale di prove sulla finestra reale non è ancora eseguita. Emenda ADR-0056 (v1.7) | §2.2.1, §2.6.6, C.2, C.4 |</span></span>\n<span class="line"><span>| ADR-0061 | Budget iniziale della console | Il limite iniziale della console passa da 700 a 720 kB (`BUDGET.console.initialKB` in `web/scripts/esbuild.mjs`); totale, workbench e WASM invariati; la console resta un file unico coperto da SRI. Emenda ADR-0020 (v1.7) | §4.4 |</span></span></code></pre></div><hr><h2 id="_5-verifiche-che-spettano-all-owner" tabindex="-1">5. Verifiche che spettano all&#39;owner <a class="header-anchor" href="#_5-verifiche-che-spettano-all-owner" aria-label="Permalink to &quot;5. Verifiche che spettano all&#39;owner&quot;">​</a></h2><ol><li><strong>Citazioni alla lettera.</strong> I blocchi «testo attuale» sono estratti automaticamente da <code>Specifications.md</code> v1.6 (2027 righe): se lo spec cambia prima dell&#39;applicazione, vanno riestratti.</li><li><strong>ADR-0057, punto 7 e «Contesto».</strong> Il punto 7 dice che un <code>device_id</code> che il cloud non conosce lascia il client nello stato <code>device_revoked</code>; ma il «Contesto» dell&#39;ADR, e il codice, dicono altro: il cloud risponde <code>400 VALIDATION_FAILED</code> con dettaglio <code>unknown device_id</code> (<code>services/cloud/internal/sync/service.go:128</code>) e il client riconosce <code>device_revoked</code> solo dal <code>403 FORBIDDEN</code> con <code>extra.reason</code> (<code>apps/desktop/internal/sync/transport/client.go:107-121</code>). Il testo proposto parla <strong>solo</strong> della revoca, e non promette nulla per un <code>device_id</code> sconosciuto. L&#39;ADR va letto di conseguenza (o corretto) dall&#39;owner.</li><li><strong>ADR-0057, <code>lower(name)</code>.</strong> L&#39;ADR scrive <code>hostname = lower(name)</code>; il codice (migrazione <code>0016</code>, <code>UpsertDesktopDevice</code>) usa <code>lower(btrim(name))</code>, e riattivando non azzera <code>app_version</code> né <code>Idempotency-Key</code>. Il testo proposto segue il codice; l&#39;ADR porta una nota «Come implementato».</li><li><strong>ADR-0058, punto 1.</strong> L&#39;ADR dice <code>UserManager</code> con <code>revokeTokensOnSignout: true</code>; il codice <strong>non</strong> lo imposta (un test lo verifica, <code>web/src/auth/oidc.test.ts</code>) e chiama <code>revokeTokens()</code> a parte, a miglior sforzo. Il testo proposto segue il codice; l&#39;ADR porta una nota «Come implementato».</li><li><strong>ADR-0058, passo 0.</strong> L&#39;ADR chiedeva di accertare la causa del rientro senza password su E2BR prima dell&#39;accettazione. L&#39;owner ha accettato senza: il testo proposto lo dichiara come limite (back-channel non provato, causa non accertata) e non promette che il sintomo sparisca.</li><li><strong>Deriva dello spec non legata agli ADR.</strong> (a) Il DDL di <code>devices</code> (§3.2.2) non ha la colonna <code>idempotency_key</code> (migrazione <code>0012</code>) né l&#39;indice <code>devices_user_ix</code>: la proposta aggiunge solo ciò che serve ad ADR-0057. (b) L&#39;elenco delle migrazioni (riga 1020) si ferma a <code>0009</code>: la proposta aggiunge <code>0016</code> e dichiara che <code>0010</code>–<code>0015</code> non sono descritte. Se si vuole, la v1.7 può descriverle (stato dei file in <code>services/cloud/internal/db/migrations/</code>).</li><li><strong><code>features.config_dir_v2</code> non è nello spec.</strong> ADR-0052 lo prevedeva (§2.6.6) e ADR-0059 ne dipende: la riga è proposta al §3.3. Verificare il testo contro <code>api/config-profile.schema.json</code>.</li><li><strong>Versioni.</strong> La v1.7 dello spec è una versione del <strong>documento</strong>: non coincide con la versione del prodotto (1.7.2). Il registro lo dice scrivendo «già implementati (1.5.0 e 1.7.2)».</li><li><strong>Voci senza ADR (§4.9).</strong> Il paragrafo sull&#39;aggiornamento senza perdere il database è un&#39;aggiunta facoltativa, non una deviazione.</li><li><strong>ADR-0045…0051 restano non recepiti</strong> (e ADR-0023): lo spec dice ancora Wails v2 (D-07, A-03, §4.5). Il testo proposto non nomina Wails v3. Se l&#39;owner accetta ADR-0051, il recepimento è un altro passo.</li><li><strong><code>CLAUDE.md</code></strong> cita «<code>Specifications.md</code> (v1.5 …)» e dice che ADR-0051 è «in proposta»: è dell&#39;owner e non l&#39;ho toccato.</li><li><strong>Sezioni che gli ADR citano, controllate sullo spec v1.6:</strong> ADR-0057 → §1.7 (righe 286-287), §2.6.1, §3.2.2, §3.5.1; ADR-0058 → §1.3, §3.3.1, D-08 (riga 209); ADR-0059 → §2.8.2, §3.4.6, §3.5.2; ADR-0060 → §2.6.6, §2.2.1, C.2, C.4; ADR-0061 → <strong>§4.4</strong> (l&#39;ADR dice che il budget «non è nello spec»: è in §4.4, riga 1870, e nella riga di ADR-0020 di C.4; l&#39;ADR è stato corretto). Tutti i numeri di riga e le sezioni citati dagli ADR sono corretti sulla v1.6.</li></ol><hr><h2 id="_6-dopo-il-recepimento" tabindex="-1">6. Dopo il recepimento <a class="header-anchor" href="#_6-dopo-il-recepimento" aria-label="Permalink to &quot;6. Dopo il recepimento&quot;">​</a></h2><ul><li>Gli ADR 0052 e 0057–0061 passano a «accettata (recepita nello spec v1.7)» nell&#39;indice <a href="./adr/"><code>docs/adr/README.md</code></a>, e ognuno riceve la riga <strong>Recepito in</strong> (come ADR-0053…0056): <code>Specifications.md</code> v1.7 (2026-11-16) con le sezioni elencate in §1.</li><li>Il comando di controllo del nome: <code>command grep -n -i memobrain Specifications.md</code> deve dare solo le eccezioni del §3.1; <code>task lint-brand</code> non controlla lo spec (<code>Specifications.md</code> è <code>history</code> nell&#39;allowlist): la verifica è a mano.</li><li>Questo documento resta come storia, con una nota in testa come <code>spec-v1.2-proposta.md</code>.</li><li><code>CHANGELOG.md</code>: la voce <em>Documentazione</em> di <em>Unreleased</em> si aggiorna («<code>Specifications.md</code> v1.7»); roadmap §13-quaterdecies: «spec v1.7 applicato».</li></ul>',158)])])}const m=a(s,[["render",n]]);export{g as __pageData,m as default};
